package com.labmaker.app;
import okhttp3.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.zip.*;
final class ContributionUpload {
 static final int MAX_FILE=20*1024*1024,MAX_TOTAL=40*1024*1024;
 static final class Item {final String name,ext,hash;final int index,size;final File file;Item(String name,String ext,String hash,int index,int size,File file){this.name=name;this.ext=ext;this.hash=hash;this.index=index;this.size=size;this.file=file;}}
 final FeedbackUpload http;ContributionUpload(FeedbackUpload http){this.http=http;}
 static String hash(byte[] data)throws Exception {StringBuilder h=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(data))h.append(String.format("%02x",v&255));return h.toString();}
 static byte[] read(Item item)throws Exception {byte[] bytes;try(InputStream in=new FileInputStream(item.file)){bytes=FeedbackUpload.bounded(in,MAX_FILE);}if(bytes.length!=item.size||!hash(bytes).equals(item.hash))throw new IOException("待贡献文件已变化，请重新选择");return bytes;}
 static void word(byte[] bytes)throws Exception {boolean document=false,types=false;int count=0;long total=0;Set<String> names=new HashSet<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry e;byte[] block=new byte[8192];while((e=zip.getNextEntry())!=null){if(++count>3000||!names.add(e.getName()))throw new IOException("Word 文件结构无效");document|=e.getName().equals("word/document.xml");types|=e.getName().equals("[Content_Types].xml");int n;while((n=zip.read(block))!=-1){total+=n;if(total>64*1024*1024)throw new IOException("Word 解压后过大");}}}if(!document||!types)throw new IOException("请选择有效的 DOCX 报告");}
 static List<Item> plan(File cache,String id,String exp,String kind,JSONArray raw)throws Exception {
  if(!id.matches("[a-f0-9-]{36}")||exp.isEmpty()||exp.length()>100||exp.chars().anyMatch(c->c=='/'||c==92||c<32)||exp.equals(".")||exp.equals("..")||(!kind.equals("variant")&&!kind.equals("report"))||raw==null||raw.length()<1||raw.length()>11)throw new IOException("贡献配置无效");
  List<Item> items=new ArrayList<>();long total=0;int photos=0,docs=0;Set<String> names=new HashSet<>();File folder=new File(cache,"contribution-uploads/"+id).getCanonicalFile();if(!folder.toPath().startsWith(cache.getCanonicalFile().toPath()))throw new IOException("贡献目录无效");
  for(int i=0;i<raw.length();i++){JSONObject row=raw.getJSONObject(i);String ext=row.optString("extension"),name=row.optString("name"),sha=row.optString("sha256");long size=row.optLong("size",-1);if(!Arrays.asList("json","jpg","docx").contains(ext)||row.optInt("index",-1)!=i||!sha.matches("[a-f0-9]{64}")||size<1||size>MAX_FILE||!names.add(name))throw new IOException("贡献文件信息无效");total+=size;if(total>MAX_TOTAL)throw new IOException("贡献文件合计超过 40 MB");File file=new File(folder,i+"."+ext).getCanonicalFile();if(!file.toPath().startsWith(folder.toPath())||!file.isFile()||file.length()!=size)throw new IOException("待贡献文件缺失或大小不符");Item item=new Item(name,ext,sha,i,(int)size,file);byte[] bytes=read(item);
   if(kind.equals("variant")){if(raw.length()!=1||!name.equals("自建变体_"+exp+".json")||!ext.equals("json")||size>8*1024*1024)throw new IOException("变体贡献格式无效");JSONObject object=new JSONObject(new String(bytes,StandardCharsets.UTF_8));int entries=0;for(Iterator<String> keys=object.keys();keys.hasNext();){String section=keys.next();if(section.equals("__note")){if(!(object.get(section) instanceof String)||object.getString(section).length()>1000)throw new IOException("变体备注无效");continue;}if(!Arrays.asList("实验原理","实验方法","误差分析","结论").contains(section))throw new IOException("变体章节无效");JSONArray texts=object.getJSONArray(section);for(int t=0;t<texts.length();t++){if(!(texts.get(t) instanceof String)||texts.getString(t).trim().isEmpty()||texts.getString(t).length()>20000||++entries>500)throw new IOException("变体正文无效");}}if(entries==0)throw new IOException("未选择贡献变体");}
   else if(ext.equals("jpg")){if(!name.matches("photo-[1-9][.]jpg")||++photos>9||size>2*1024*1024||bytes.length<3||(bytes[0]&255)!=255||(bytes[1]&255)!=216)throw new IOException("贡献照片无效");}
   else if(ext.equals("docx")){if(!name.equals("report.docx")||++docs>1||size>16*1024*1024)throw new IOException("贡献 Word 文件无效");word(bytes);}
   else {if(i!=raw.length()-1||!name.equals("manifest.json")||size>32768)throw new IOException("贡献清单无效");JSONObject manifest=new JSONObject(new String(bytes,StandardCharsets.UTF_8));if(!manifest.optString("kind").equals("report")||!manifest.optString("exp").equals(exp)||!manifest.optString("score").matches("(?:7|8|9)(?:[.]0|[.]5)?|10(?:[.]0)?")||manifest.optString("note").length()>1000)throw new IOException("报告分数或清单无效");}
   items.add(item);
  }
  if(kind.equals("report")&&(photos+docs==0||!items.get(items.size()-1).name.equals("manifest.json")))throw new IOException("未选择报告或照片");return items;
 }
 Map<String,HttpUrl> tickets(JSONObject raw,List<Item> files,String prefix)throws Exception {JSONArray items=raw.optJSONArray("items");if(!raw.optBoolean("ok")||items==null||items.length()!=files.size())throw new IOException("贡献凭证服务协议不兼容");Map<String,HttpUrl> result=new HashMap<>();String group=null;for(int i=0;i<items.length();i++){JSONObject it=items.getJSONObject(i);String key=it.optString("key"),object=it.optString("objectKey");Item file=null;for(Item candidate:files)if(key.equals(prefix+candidate.name))file=candidate;if(file==null||result.containsKey(key)||it.optLong("size",-1)!=file.size)throw new IOException("贡献凭证与文件不匹配");String parent=object.substring(0,Math.max(0,object.lastIndexOf('/')+1)),root=prefix.substring(0,prefix.lastIndexOf('/',prefix.length()-2)+1);String uuid=parent.startsWith(root)?parent.substring(root.length()):"";if(!uuid.matches("[a-f0-9-]{36}/")||!object.equals(parent+file.name)||group!=null&&!group.equals(parent))throw new IOException("贡献凭证目录无效");group=parent;HttpUrl url=HttpUrl.parse(it.optString("putUrl"));HttpUrl wanted=http.destination.newBuilder().encodedPath("/").addPathSegments(object).build();if(url==null||!url.scheme().equals(wanted.scheme())||!url.host().equals(wanted.host())||url.port()!=wanted.port()||!url.username().isEmpty()||!url.password().isEmpty()||url.fragment()!=null||!url.encodedPath().equals(wanted.encodedPath())||url.query()==null||url.toString().length()>8192)throw new IOException("贡献上传地址无效");result.put(key,url);}return result;}
 JSONObject submit(String id,String exp,String kind,List<Item> files,FeedbackUpload.Work work)throws Exception {
  String prefix="contributions/"+(kind.equals("variant")?"variants":"reports")+"/"+exp+"/"+id+"/";JSONArray requested=new JSONArray();for(Item f:files)requested.put(new JSONObject().put("key",prefix+f.name).put("size",f.size));int sent=0;boolean uncertain=false;try{Map<String,HttpUrl> urls;try(Response response=http.execute(new Request.Builder().url(http.endpoint).post(RequestBody.create(new JSONObject().put("files",requested).toString(),MediaType.get("application/json; charset=utf-8"))).build(),work)){if(!response.isSuccessful()||response.body()==null)throw new IOException("贡献凭证服务暂不可用");urls=tickets(new JSONObject(new String(FeedbackUpload.bounded(response.body().byteStream(),32768),StandardCharsets.UTF_8)),files,prefix);}
   for(Item f:files){if(work.cancelled.get())break;byte[] bytes=read(f);if(work.cancelled.get())break;uncertain=true;work.putStarted=true;try(Response response=http.execute(new Request.Builder().url(urls.get(prefix+f.name)).header("Content-Type","application/octet-stream").header("x-cos-forbid-overwrite","true").put(RequestBody.create(bytes,MediaType.get("application/octet-stream"))).build(),work)){if(!response.isSuccessful())break;sent++;uncertain=false;}}
  }catch(Exception error){if(sent==0&&!uncertain&&!work.cancelled.get())throw new IOException(error instanceof IOException?error.getMessage():"贡献服务响应无效");}finally{work.call.set(null);}return new JSONObject().put("state",sent==files.size()?"sent":uncertain?"unknown":sent>0?"partial":"cancelled").put("sent",sent).put("total",files.size());
 }
}
